import{_ as t,o,c as d,a2 as a}from"./chunks/framework.BEUshCVJ.js";const u=JSON.parse('{"title":"知识库","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/materials.md","filePath":"zh/guide/materials.md","lastUpdated":1793456875000}'),r={name:"zh/guide/materials.md"};function c(l,e,n,i,s,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="知识库" tabindex="-1">知识库 <a class="header-anchor" href="#知识库" aria-label="Permalink to &quot;知识库&quot;">​</a></h1><p>本页介绍如何把你自己和这场会议的背景告诉 MeetCue，让提示基于你的真实经历而不是泛泛而谈，以及如何查看和修改发给提示模型的指令。</p><h2 id="描述你的角色" tabindex="-1">描述你的角色 <a class="header-anchor" href="#描述你的角色" aria-label="Permalink to &quot;描述你的角色&quot;">​</a></h2><p>在 <strong>设置 › 提示 › 我的角色</strong> 中用一句话介绍自己，例如：</p><blockquote><p>网络架构师，8 年数据中心运维经验</p></blockquote><p>要点模型会从这个角度组织要点。</p><h2 id="添加文件" tabindex="-1">添加文件 <a class="header-anchor" href="#添加文件" aria-label="Permalink to &quot;添加文件&quot;">​</a></h2><ol><li>打开 <strong>设置 › 提示</strong>。</li><li>在 <strong>知识库</strong> 下点击 <strong>添加文件…</strong>，可以一次选择多个文件。</li><li>选择简历、项目笔记、演示文稿、职位描述、议程等文件。</li></ol><p>支持的格式：</p><table tabindex="0"><thead><tr><th>类型</th><th>扩展名</th></tr></thead><tbody><tr><td>PDF</td><td><code>.pdf</code></td></tr><tr><td>Word</td><td><code>.docx</code>、<code>.docm</code></td></tr><tr><td>Excel</td><td><code>.xlsx</code>、<code>.xlsm</code>（所有工作表，按行读取单元格）</td></tr><tr><td>PowerPoint</td><td><code>.pptx</code>、<code>.pptm</code>（幻灯片文字和备注）</td></tr><tr><td>OpenDocument</td><td><code>.odt</code>、<code>.ods</code>、<code>.odp</code></td></tr><tr><td>其他文档</td><td><code>.rtf</code>、<code>.html</code>、<code>.htm</code></td></tr><tr><td>文本</td><td><code>.txt</code>、<code>.md</code>、<code>.csv</code>、<code>.tsv</code>、<code>.json</code>、<code>.yaml</code>、<code>.log</code></td></tr></tbody></table><p>MeetCue 在本机抽取文字并显示字数。旧版 <code>.doc</code>、<code>.xls</code>、<code>.ppt</code> 无法读取，请先在 Office 中另存为 <code>.docx</code>、<code>.xlsx</code> 或 <code>.pptx</code>。没有文字层的扫描版 PDF 抽不出文字，请先用文字识别功能导出。再次添加同一个文件会替换之前的版本。</p><h2 id="知识库如何使用" tabindex="-1">知识库如何使用 <a class="header-anchor" href="#知识库如何使用" aria-label="Permalink to &quot;知识库如何使用&quot;">​</a></h2><ul><li><strong>较短的文件</strong>（合计约 3000 字以内）每个问题都会整份附上。</li><li><strong>较长的文件</strong>会切成段落。每个问题会挑出与它共同词语最多的段落，最多约 2400 字，附在这个问题的请求里，同时附上每个文件的简短概要。检索在本机完成，耗时远不到一毫秒，不会拖慢提示。</li></ul><p>提示模型会被要求以这些资料中的经历为基础组织回答，用你真实的项目、名称和数据，而不是编造。</p><p>想知道某个问题会带上什么，在 <strong>试一个问题</strong> 中输入问题并点击 <strong>查看匹配</strong>。不会发送任何内容。</p><h2 id="会发送什么" tabindex="-1">会发送什么 <a class="header-anchor" href="#会发送什么" aria-label="Permalink to &quot;会发送什么&quot;">​</a></h2><ul><li>概要和每个问题匹配到的段落会发给要点模型。</li><li>资料中最有辨识度的词（产品名、缩写、人名）会作为热词发给语音识别供应商，让这些词识别得更准。</li><li>全文只留在你的电脑上，也不会包含在诊断信息里。</li></ul><p>概要放在指令中整场会议都不变的部分。支持提示缓存的供应商从第二个问题起对这部分收费会低很多。</p><p>想配合模拟面试试一试，可以用示例职位描述：<a href="https://github.com/Amazingkenneth/meetcue/blob/HEAD/samples/materials/jd-software-engineer.md" target="_blank" rel="noreferrer">jd-software-engineer.md</a> 或 <a href="https://github.com/Amazingkenneth/meetcue/blob/HEAD/samples/materials/jd-security-ai.md" target="_blank" rel="noreferrer">jd-security-ai.md</a>。它们与<a href="/meetcue/zh/guide/mock-interview">模拟面试</a>中的内置示例面试对应。</p><h2 id="修改提示词" tabindex="-1">修改提示词 <a class="header-anchor" href="#修改提示词" aria-label="Permalink to &quot;修改提示词&quot;">​</a></h2><p><strong>设置 › 提示 › 提示词</strong> 显示发给提示模型的两段提示词，并可以修改：</p><ul><li><strong>指令</strong>：每个问题都一样。占位符：<code>{role}</code>（你的角色）、<code>{materials}</code>（知识库概要）、<code>{output_language}</code>（输出语言）。</li><li><strong>问题消息</strong>：随每个问题发送。占位符：<code>{knowledge}</code>（匹配的段落）、<code>{transcript}</code>（最近的对话）、<code>{question}</code>（问题）。</li></ul><p>删掉某个占位符，对应的信息就不会再发给模型；缺少占位符时 MeetCue 会提醒你。请保留指令中描述的回复格式（编号的 JSON 行、一行 <code>---</code>、再接示范回答），否则面板无法显示提示。</p><p>修改过的提示词会标记为 <strong>已修改</strong>。点击 <strong>恢复内置</strong> 可回到内置版本，内置版本会随 MeetCue 新版本更新。修改从下一个问题起生效，会议进行中也一样。</p><h2 id="保持精简" tabindex="-1">保持精简 <a class="header-anchor" href="#保持精简" aria-label="Permalink to &quot;保持精简&quot;">​</a></h2><p>段落按共同词语挑选，所以与问题用词一致的资料效果最好：项目笔记用会议的语言写，写明用过的技术名称。不再需要的文件可以点 <strong>移除</strong>。</p>',26)])])}const g=t(r,[["render",c]]);export{u as __pageData,g as default};
